recipes.code:
{
  "inputs": [
    {
      "id": "crustapi-api-key",
      "type": "promptString",
      "description": "Your CrustAPI key from crustapi.com/app (free tier: 3,000 credits/month)",
      "password": true
    }
  ],
  "servers": {
    "search": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "crustapi-mcp@0.3.1"
      ],
      "env": {
        "CRUSTAPI_API_KEY": "${input:crustapi-api-key}"
      }
    }
  }
}
